import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/ChatSidebar.css"; // ✅ Use your styles folder

const ChatSidebar = ({ onSelectConversation, selectedConversation }) => {
  const [conversations, setConversations] = useState([]);
  const [searchUsername, setSearchUsername] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [user, setUser] = useState(null);

  // ✅ Load user from localStorage
  useEffect(() => {
    const storedUser = JSON.parse(localStorage.getItem("user"));
    setUser(storedUser);
  }, []);

  // ✅ Fetch conversations
  useEffect(() => {
    const fetchConversations = async () => {
      try {
        if (!user?._id) return;
        const res = await axios.get(`/api/conversations/${user._id}`);
        setConversations(res.data);
      } catch (err) {
        console.error("Error fetching conversations:", err);
      }
    };
    fetchConversations();
  }, [user]);

  const handleSearch = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`/api/profile/search?username=${searchUsername}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setSearchResults(res.data);
    } catch (err) {
      console.error("Error searching users:", err);
    }
  };

  const handleUserClick = (selectedUser) => {
    onSelectConversation({ participants: [user, selectedUser] });
    setSearchUsername("");
    setSearchResults([]);
  };

  return (
    <div className="chat-sidebar">
      <h4>Messages</h4>
      <input
        type="text"
        placeholder="Search user..."
        value={searchUsername}
        onChange={(e) => setSearchUsername(e.target.value)}
      />
      <button onClick={handleSearch}>Search</button>

      {searchResults.length > 0 && (
        <div className="search-results">
          {searchResults.map((u) => (
            <div
              key={u._id}
              className="search-result-item"
              onClick={() => handleUserClick(u)}
            >
              {u.userId?.username || u.username}
            </div>
          ))}
        </div>
      )}

      <div className="conversations">
        {conversations.length === 0 ? (
          <em>No conversations found.</em>
        ) : (
          conversations.map((c, i) => (
            <div
              key={i}
              className={`conversation-item ${
                selectedConversation?._id === c._id ? "selected" : ""
              }`}
              onClick={() => onSelectConversation(c)}
            >
              {c.participantUsernames?.filter((name) => name !== user?.username).join(", ") || "Chat"}
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ChatSidebar;
